import sys
import math

def get_ints():
	return list(map(int, sys.stdin.readline().strip().split()))

def docase():
	[n] = get_ints()
	aa = get_ints()
	ee = [list() for _ in range(0, n)]
	for _ in range(1, n):
		[u, v] = get_ints()
		if v != 1:
			ee[u - 1].append(v)
		if u != 1:
			ee[v - 1].append(u)
	stack = [(1, 0, ee[0], aa[0], 0, 0)]
	while stack:
		(a, b, cc, gnode, gsum, best) = stack[-1]
		if cc:
			c = cc.pop()
			if c == b:
				continue
			stack.append((c, a, ee[c - 1], aa[c - 1], 0, 0))
		else:
			stack.pop()
			g = gnode
			s = max(gsum, gsum + best)
			if not stack:
				print(s)
			else:
				(a, b, cc, gnode, gsum, best) = stack.pop()
				diff = s - g
				if gsum != 0 and diff < best:
					diff = best
				stack.append((a, b, cc, math.gcd(gnode, g), gsum + g, diff))
[t] = get_ints()
for _ in range(0, t):
	docase()
